function ActivityTimeline(props){
          if (Array.isArray(props.lanes)) {
            var laneContent = props.lanes.length === 0
              ? '<div class="route-detail-empty">' + escapeHtml(localize(props.locale, "暂无 agent 活动", "No agent activity yet")) + "</div>"
              : '<div class="command-lane-board" data-command-lane-board="true">' + props.lanes.map(function (lane) {
                return '<section class="command-lane" data-command-lane="' + escapeHtml(lane.id) + '">' +
                  '<div class="command-lane-header"><div><strong>' + escapeHtml(lane.title) + '</strong><p style="margin:4px 0 0; color:var(--ink-3);">' + escapeHtml(lane.subtitle || "") + '</p></div>' + StatusPill({ tone: lane.tone || "neutral", children: escapeHtml(lane.badge || lane.title) }) + '</div>' +
                  '<div class="command-lane-events">' + lane.events.map(function (event) {
                    return '<article class="command-event-row' + (props.expandedEventId === event.id ? " is-expanded" : "") + '" data-command-event="' + escapeHtml(event.id) + '">' +
                      '<button type="button" class="command-event-head" data-action="command-toggle-event" data-payload="' + escapeHtml(event.id) + '" aria-label="' + escapeHtml(localize(props.locale, "展开事件上下文", "Expand event context")) + '">' +
                        '<span style="display:flex; align-items:center; gap:10px;"><span class="timeline-dot is-' + escapeHtml(event.tone || "neutral") + '" aria-hidden="true"></span><strong>' + escapeHtml(event.title) + '</strong></span>' +
                        '<span style="display:flex; align-items:center; gap:10px; color:var(--ink-3);"><span>' + escapeHtml(event.timestampLabel) + '</span><span>' + escapeHtml(props.expandedEventId === event.id ? "−" : "+") + '</span></span>' +
                      '</button>' +
                      '<p style="margin:0; color:var(--ink-2);">' + escapeHtml(event.detail) + '</p>' +
                      (props.expandedEventId === event.id ? '<div class="command-event-context">' + (event.context || []).map(function (line) {
                        return '<div>' + escapeHtml(line) + "</div>";
                      }).join("") + "</div>" : "") +
                    "</article>";
                  }).join("") + "</div>" +
                "</section>";
              }).join("") + "</div>";

            return ShellCard({
              eyebrow: localize(props.locale, "活动时间线", "Activity Timeline"),
              title: escapeHtml(localize(props.locale, "多代理活动总线", "Multi-agent event bus")),
              children: laneContent
            });
          }

          var events = props.runs
            .map(function (run) {
              var status = run.status;
              return {
                id: run.id,
                tone: status === "completed" ? "success" : status === "failed" || status === "failed_tests" ? "warning" : "neutral",
                title: run.task,
                detail: describeRunHealth(run, props.locale),
                timestamp: run.completedAt || run.startedAt
              };
            })
            .sort(function (left, right) {
              return new Date(right.timestamp).getTime() - new Date(left.timestamp).getTime();
            })
            .slice(0, 4);

          var content = events.length === 0
            ? '<p>' + escapeHtml(localize(props.locale, "Friday 正在待命。", "Friday is standing by.")) + "</p>"
            : '<div class="timeline-list">' + events.map(function (event) {
              return '<div class="timeline-item">' +
                '<span class="timeline-dot is-' + escapeHtml(event.tone) + '" aria-hidden="true"></span>' +
                '<article class="timeline-card">' +
                  '<header><p class="timeline-card-title">' + escapeHtml(event.title) + '</p><small>' + escapeHtml(formatRelativeTime(event.timestamp, props.locale, BASE_CLOCK)) + "</small></header>" +
                  '<p>' + escapeHtml(event.detail || localize(props.locale, "最近一次运行还在处理中。", "The latest run is still in progress.")) + "</p>" +
                "</article>" +
              "</div>";
            }).join("") + "</div>";

          return ShellCard({
            eyebrow: localize(props.locale, "活动时间线", "Activity Timeline"),
            title: escapeHtml(localize(props.locale, "今天的执行脉冲", "Today's execution pulse")),
            children: content
          });
        }
